package au.com.roningroup.patrollink;

import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.Toast;import androidx.core.content.ContextCompat;import org.json.JSONObject;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.concurrent.*;

/** Preconfigured update channel. Downloads an APK, then Android's own installer requires user approval. */
public final class AppUpdateManager {
    private static final String MANIFEST="https://raw.githubusercontent.com/RoninMerc/ronin-os/patrol-link-v141-secure-autologin-updates/dist/patrol-link-update.json";
    private static final ExecutorService IO=Executors.newSingleThreadExecutor();
    private final Activity a;private final Handler h=new Handler(Looper.getMainLooper());private long downloadId;
    public AppUpdateManager(Activity a){this.a=a;downloadId=a.getPreferences(0).getLong("update_download_id",0);if(downloadId>0)h.post(this::poll);}
    public void autoCheck(){long last=a.getPreferences(0).getLong("update_check",0);if(System.currentTimeMillis()-last>6*60*60*1000L)h.postDelayed(()->check(false),12000);}
    public void check(boolean showNone){a.getPreferences(0).edit().putLong("update_check",System.currentTimeMillis()).apply();IO.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(MANIFEST).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setUseCaches(false);if(c.getResponseCode()!=200)throw new IOException();String text=read(c.getInputStream());JSONObject o=new JSONObject(text);int code=o.getInt("versionCode");if(code>BuildConfig.VERSION_CODE)h.post(()->offer(o));else if(showNone)toast("TRL Patrol Link is up to date.");}catch(Exception e){if(showNone)toast("Update check unavailable. Try again later.");}});}
    private void offer(JSONObject o){String name=o.optString("versionName","new version");new AlertDialog.Builder(a).setTitle("TRL Patrol Link update available").setMessage("Version "+name+" is ready. Download it now? Android will ask you to approve installation when the download finishes.").setPositiveButton("Download update",(d,w)->download(o)).setNegativeButton("Later",null).show();}
    private void download(JSONObject o){try{String url=o.getString("apk"),sha=o.optString("sha256","");DownloadManager dm=a.getSystemService(DownloadManager.class);DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url)).setTitle("TRL Patrol Link "+o.optString("versionName","")).setDescription("Downloading TRL Patrol Link update").setMimeType("application/vnd.android.package-archive").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setDestinationInExternalFilesDir(a,android.os.Environment.DIRECTORY_DOWNLOADS,"TRL-Patrol-Link-update.apk");downloadId=dm.enqueue(r);a.getPreferences(0).edit().putLong("update_download_id",downloadId).putString("update_sha",sha).apply();h.postDelayed(this::poll,1500);toast("Update download started.");}catch(Exception e){toast("Could not start update download.");}}
    private void poll(){if(downloadId<=0)return;DownloadManager dm=a.getSystemService(DownloadManager.class);try(Cursor c=dm.query(new DownloadManager.Query().setFilterById(downloadId))){if(c==null||!c.moveToFirst()){clear();return;}int st=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(st==DownloadManager.STATUS_SUCCESSFUL){Uri u=dm.getUriForDownloadedFile(downloadId);if(u==null){clear();return;}String expected=a.getPreferences(0).getString("update_sha","");if(!expected.isEmpty()){String path=c.getString(c.getColumnIndexOrThrow(DownloadManager.COLUMN_LOCAL_URI));if(path!=null&&path.startsWith("file:")){try{String got=sha256(new File(Uri.parse(path).getPath()));if(!expected.equalsIgnoreCase(got)){toast("Update verification failed. Download discarded.");dm.remove(downloadId);clear();return;}}catch(Exception e){toast("Update verification failed.");clear();return;}}}install(u);return;}if(st==DownloadManager.STATUS_FAILED){toast("Update download failed.");clear();return;}}catch(Exception e){}h.postDelayed(this::poll,1800);}
    private void install(Uri u){if(Build.VERSION.SDK_INT>=26&&!a.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(a).setTitle("Allow TRL Patrol Link updates").setMessage("Android needs one permission so Patrol Link can hand downloaded updates to the system installer. You will still approve every APK installation.").setPositiveButton("Open setting",(d,w)->a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())))).setNegativeButton("Not now",null).show();h.postDelayed(this::poll,5000);return;}Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(u,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_ACTIVITY_NEW_TASK);try{a.startActivity(i);clear();}catch(Exception e){toast("Android could not open the installer.");}}
    private void clear(){downloadId=0;a.getPreferences(0).edit().remove("update_download_id").remove("update_sha").apply();}
    private String read(InputStream in)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[2048];for(int n;(n=in.read(x))>0;)b.write(x,0,n);return b.toString("UTF-8");}
    private String sha256(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];for(int n;(n=in.read(b))>0;)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte x:d.digest())s.append(String.format("%02x",x));return s.toString();}
    private void toast(String s){h.post(()->Toast.makeText(a,s,Toast.LENGTH_LONG).show());}
}
